// Minimal Gravity Flip Game
// Assumes an HTML canvas with id="game"
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.offsetWidth;
canvas.height = canvas.offsetHeight;

// Player
const player = {
  x: 50,
  y: canvas.height / 2,
  w: 20,
  h: 20,
  vy: 0,
  speed: 2,
  gravity: 0.4,
  dir: 1 // 1 = down, -1 = up
};

let obstacles = [];

